    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(16, 24, 40, 0.92);
        --panel-border: rgba(148, 163, 184, 0.18);
        --text: #e5eefb;
        --muted: #9fb0c8;
        --accent: #7dd3fc;
        --accent-strong: #38bdf8;
        --error: #fca5a5;
        --success: #86efac;
        --shadow: 0 28px 60px rgba(2, 6, 23, 0.5);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
        font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
