        position: absolute;
        top: 12px;
        left: 12px;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: #f8fafc;
        color: #020617;
        text-decoration: none;
        transform: translateY(-140%);
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        width: min(100%, 440px);
      }

      .card {
        padding: clamp(1.5rem, 4vw, 2rem);
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        background: var(--panel);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      h1 {
        margin: 0 0 0.5rem;
        font-size: clamp(1.75rem, 4vw, 2.2rem);
        line-height: 1.15;
      }

      .intro {
        margin: 0 0 1.5rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        display: grid;
        gap: 0.6rem;
      }

      .checkbox-row {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.85rem;
        align-items: start;
        padding: 1rem;
        border: 1px solid rgba(125, 211, 252, 0.18);
        border-radius: 16px;
        background: rgba(15, 23, 42, 0.78);
      }

      input[type="checkbox"] {
        width: 1.15rem;
        height: 1.15rem;
        margin: 0.15rem 0 0;
        accent-color: var(--accent-strong);
      }

      label {
        font-weight: 600;
      }

      .required-mark {
        color: #fda4af;
      }

      .helper-text,
      .error-text,
      .status {
        margin: 0;
        font-size: 0.95rem;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--error);
      }

      .status {
        min-height: 1.5rem;
        color: var(--success);
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.2rem;
        font: inherit;
        font-weight: 700;
        color: #020617;
        background: linear-gradient(135deg, #7dd3fc, #38bdf8);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.05);
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 3px;
      }

      .checkbox-invalid {
        border-color: rgba(252, 165, 165, 0.9);
      }

      .visually-hidden {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      @media (max-width: 480px) {
        body {
          padding: 16px;
        }
      }

      @media (forced-colors: active) {
        .skip-link,
        .card,
        .checkbox-row,
        button {
          border: 1px solid CanvasText;
        }

        button {
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <section class="card" aria-labelledby="page-title">
        <h1 id="page-title">Review and continue</h1>
        <p class="intro">Confirm your consent before submitting the form.</p>

        <form id="consent-form" novalidate>
          <div class="form-field">
            <div class="checkbox-row" id="consent-field">
              <input
                id="consent"
                name="consent"
                type="checkbox"
                required
                aria-describedby="consent-help"
              >
              <label for="consent">
                I agree to the <a href="#" target="_blank" rel="noopener noreferrer">Terms of Use</a>
                <span class="required-mark" aria-hidden="true">*</span>
                <span class="visually-hidden">Required</span>
              </label>
            </div>
            <p class="helper-text" id="consent-help">Required to continue.</p>
            <p class="error-text" id="consent-error" hidden>Error: You must agree to the Terms of Use to continue.</p>
          </div>

          <button type="submit">Agree and continue</button>
          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("consent-form");
      const consent = document.getElementById("consent");
      const consentField = document.getElementById("consent-field");
      const error = document.getElementById("consent-error");
      const status = document.getElementById("form-status");

      function showError() {
        error.hidden = false;
        consent.setAttribute("aria-invalid", "true");
        consent.setAttribute("aria-describedby", "consent-help consent-error");
        consentField.classList.add("checkbox-invalid");
      }

      function clearError() {
        error.hidden = true;
        consent.removeAttribute("aria-invalid");
        consent.setAttribute("aria-describedby", "consent-help");
        consentField.classList.remove("checkbox-invalid");
      }

      form.addEventListener("submit", (event) => {
        status.textContent = "";

        if (!consent.checked) {
          event.preventDefault();
          showError();
          consent.focus();
          return;
        }

        event.preventDefault();
        clearError();
        status.textContent = "Consent recorded. You can proceed.";
      });

      consent.addEventListener("change", () => {
        if (consent.checked) {
          clearError();
        }
      });
    </script>
  </body>
</html>
