const fs = require('fs');
const { chromium } = require('playwright');
const axeSource = require('axe-core').source;

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

  async function run(name, setup) {
    await page.setContent(html, { waitUntil: 'load' });
    if (setup) await setup();
    await page.addScriptTag({ content: axeSource });
    const result = await page.evaluate(async () => await window.axe.run());
    return [name, result.violations
      .filter((v) => !v.tags.includes('best-practice'))
      .map((v) => ({
        id: v.id,
        impact: v.impact,
        targets: v.nodes.map((n) => n.target)
      }))];
  }

  const summary = Object.fromEntries([
    await run('initial'),
    await run('invalid_submit', async () => {
      await page.click('button[type="submit"]');
    })
  ]);

  await browser.close();
  const failures = Object.values(summary).flat();
  console.log(JSON.stringify(summary));
  process.exit(failures.length ? 1 : 0);
})().catch((error) => {
  console.error(error.stack || error.message);
  process.exit(1);
});
